// Intro-level Life Sciences quizzes — bb60 through bb73
// Foundational, high-school-biology-level content (balances the MCAT-level bioBiochem.js quizzes)
export const INTRO_LIFE_SCI_QUIZZES = [
  {
    id:'bb101', cat:'Life Sciences', title:'Intro to Cells: Structure & Function', diff:'Easy',
    qs:[
      { q:`What is considered the basic unit of life?`, ch:[`The atom`,`The cell`,`The tissue`,`The organ`], ans:1, exp:`The cell is the smallest unit that can carry out all the functions of life, such as growth and reproduction. All living things are made of one or more cells.` },
      { q:`Which type of cell lacks a nucleus?`, ch:[`Prokaryotic cell`,`Eukaryotic cell`,`Plant cell`,`Animal cell`], ans:0, exp:`Prokaryotic cells, such as bacteria, do not have a nucleus or membrane-bound organelles. Their DNA floats freely in the cytoplasm.` },
      { q:`Which organelle is often called the "powerhouse of the cell"?`, ch:[`Nucleus`,`Ribosome`,`Mitochondrion`,`Golgi apparatus`], ans:2, exp:`Mitochondria break down food molecules to produce ATP, the cell's main energy source, which is why they are nicknamed the powerhouse of the cell.` },
      { q:`Which structure houses the cell's DNA in a eukaryotic cell?`, ch:[`Cell membrane`,`Nucleus`,`Vacuole`,`Cytoplasm`], ans:1, exp:`The nucleus is a membrane-bound organelle that stores the cell's genetic material (DNA) and controls the cell's activities.` },
      { q:`What structure controls what materials enter and exit the cell?`, ch:[`Cell wall`,`Nucleolus`,`Cell membrane`,`Cytoskeleton`], ans:2, exp:`The cell membrane surrounds the cell and is selectively permeable, meaning it regulates which substances can pass in and out.` },
      { q:`Which organelles are the sites of protein synthesis?`, ch:[`Ribosomes`,`Lysosomes`,`Chloroplasts`,`Vacuoles`], ans:0, exp:`Ribosomes read genetic instructions from mRNA and link amino acids together to build proteins.` },
      { q:`Which structure provides rigid shape and protection in plant cells but is absent in animal cells?`, ch:[`Cell membrane`,`Cell wall`,`Cytoplasm`,`Nucleus`], ans:1, exp:`Plant cells have a rigid cell wall made of cellulose surrounding the cell membrane, giving structural support. Animal cells lack a cell wall.` },
      { q:`What is the gel-like substance that fills a cell and suspends its organelles?`, ch:[`Cytoplasm`,`Nucleoplasm`,`Plasma`,`Chlorophyll`], ans:0, exp:`Cytoplasm is the jelly-like fluid inside the cell membrane in which the organelles are suspended and many cellular reactions occur.` },
      { q:`Which organelle packages and ships proteins to their destinations, similar to a post office?`, ch:[`Lysosome`,`Golgi apparatus`,`Mitochondrion`,`Ribosome`], ans:1, exp:`The Golgi apparatus modifies, sorts, and packages proteins and lipids received from the endoplasmic reticulum before sending them to their final destination.` },
      { q:`Which organelle contains enzymes that break down waste and worn-out cell parts?`, ch:[`Lysosome`,`Vacuole`,`Chloroplast`,`Nucleus`], ans:0, exp:`Lysosomes contain digestive enzymes that break down waste materials, damaged organelles, and foreign particles taken into the cell.` },
      { q:`Which organelle contains chlorophyll and carries out photosynthesis?`, ch:[`Mitochondrion`,`Chloroplast`,`Nucleus`,`Ribosome`], ans:1, exp:`Chloroplasts, found in plant cells and algae, contain the green pigment chlorophyll and use light energy to make sugar from carbon dioxide and water.` },
      { q:`According to cell theory, new cells are produced from:`, ch:[`Non-living matter spontaneously`,`Pre-existing cells dividing`,`Only the nucleus`,`Random chemical reactions in soil`], ans:1, exp:`One part of the cell theory states that all cells arise from pre-existing cells through cell division, not spontaneously from non-living matter.` },
      { q:`Which term describes a network of tube-like membranes involved in making and transporting proteins and lipids?`, ch:[`Endoplasmic reticulum`,`Cell wall`,`Vacuole`,`Centriole`], ans:0, exp:`The endoplasmic reticulum (ER) is a membrane network; rough ER (studded with ribosomes) helps make proteins, while smooth ER helps make lipids and detoxify substances.` },
    ]
  },
  {
    id:'bb102', cat:'Life Sciences', title:'The Cell Membrane & Transport Basics', diff:'Easy',
    qs:[
      { q:`The cell membrane is mainly made of which type of molecule arranged in a double layer?`, ch:[`Proteins`,`Phospholipids`,`Carbohydrates`,`Nucleic acids`], ans:1, exp:`The cell membrane consists mainly of a phospholipid bilayer, with the water-loving heads facing outward and the water-fearing tails facing inward.` },
      { q:`What does it mean that the cell membrane is "selectively permeable"?`, ch:[`It allows all substances to pass through freely`,`It blocks every substance from entering or leaving`,`It allows some substances through while restricting others`,`It only allows water through`], ans:2, exp:`Selective permeability means the membrane lets certain molecules pass easily while restricting or controlling the passage of others, helping the cell maintain a stable internal environment.` },
      { q:`Diffusion is the movement of particles from an area of:`, ch:[`Low concentration to high concentration`,`High concentration to low concentration`,`Equal concentration on both sides`,`High pressure to high temperature`], ans:1, exp:`Diffusion is the natural movement of particles from a region where they are more concentrated to a region where they are less concentrated, requiring no energy input.` },
      { q:`Osmosis specifically refers to the diffusion of which substance across a membrane?`, ch:[`Glucose`,`Oxygen`,`Water`,`Protein`], ans:2, exp:`Osmosis is the diffusion of water molecules across a selectively permeable membrane, moving from an area of high water concentration to low water concentration.` },
      { q:`Passive transport across a membrane is characterized by:`, ch:[`Requiring ATP and moving against the gradient`,`Requiring no cellular energy and moving with the concentration gradient`,`Only occurring in plant cells`,`Only moving large molecules`], ans:1, exp:`Passive transport, such as simple diffusion, moves substances along their concentration gradient (high to low) and does not require the cell to spend energy.` },
      { q:`Active transport differs from passive transport because it:`, ch:[`Requires energy (ATP) to move substances against their concentration gradient`,`Never involves membrane proteins`,`Only moves water`,`Always moves substances toward equilibrium`], ans:0, exp:`Active transport uses cellular energy (ATP) to move substances from an area of low concentration to high concentration, against the natural gradient.` },
      { q:`If an animal cell is placed in a hypertonic solution (more solute outside than inside), the cell will likely:`, ch:[`Swell and possibly burst`,`Shrink as water leaves the cell`,`Stay exactly the same`,`Immediately divide`], ans:1, exp:`In a hypertonic solution, water concentration is lower outside the cell, so water moves out of the cell by osmosis, causing the cell to shrink.` },
      { q:`If an animal cell is placed in a hypotonic solution (less solute outside than inside), the cell will likely:`, ch:[`Shrink and shrivel`,`Remain totally unchanged`,`Swell and possibly burst (lyse)`,`Turn into a plant cell`], ans:2, exp:`In a hypotonic solution, water is more concentrated outside the cell, so water moves into the cell by osmosis, causing it to swell and potentially burst.` },
      { q:`In facilitated diffusion, membrane proteins help molecules:`, ch:[`Move across the membrane using ATP against the gradient`,`Move across the membrane along their concentration gradient without using cellular energy`,`Be destroyed before entering the cell`,`Bond permanently to the membrane`], ans:1, exp:`Facilitated diffusion uses channel or carrier proteins to help specific molecules, like glucose, cross the membrane along their concentration gradient without requiring energy.` },
      { q:`Which type of molecule can typically pass directly through the phospholipid bilayer most easily?`, ch:[`Large charged proteins`,`Small nonpolar molecules like oxygen and carbon dioxide`,`Whole cells`,`DNA strands`], ans:1, exp:`Small, nonpolar (uncharged) molecules such as oxygen and carbon dioxide can slip directly through the lipid bilayer because they are not repelled by the hydrophobic interior.` },
      { q:`Exocytosis is the process by which a cell:`, ch:[`Takes in large particles by engulfing them`,`Releases materials to the outside by fusing a vesicle with the cell membrane`,`Divides into two daughter cells`,`Breaks down its own organelles`], ans:1, exp:`During exocytosis, a vesicle inside the cell fuses with the cell membrane, releasing its contents, such as hormones or waste, to the outside of the cell.` },
      { q:`Endocytosis is the process by which a cell:`, ch:[`Releases waste products only`,`Takes in large particles or fluids by surrounding them with the cell membrane`,`Produces new ribosomes`,`Divides its nucleus`], ans:1, exp:`In endocytosis, the cell membrane folds inward to engulf material from outside the cell, forming a vesicle that brings the material into the cell.` },
      { q:`Why do cells need active transport processes like the sodium-potassium pump?`, ch:[`To move substances along their gradient without any cost`,`To move substances against their concentration gradient, which requires energy`,`Because diffusion works for every substance`,`To break down proteins into amino acids`], ans:1, exp:`Some substances need to move from low to high concentration, against the natural gradient, which does not happen spontaneously and requires the cell to spend ATP energy.` },
    ]
  },
  {
    id:'bb103', cat:'Life Sciences', title:'Photosynthesis Basics', diff:'Easy',
    qs:[
      { q:`Which of the following best represents the overall inputs of photosynthesis?`, ch:[`Glucose and oxygen`,`Carbon dioxide and water`,`ATP and NADH`,`Nitrogen and water`], ans:1, exp:`Photosynthesis uses carbon dioxide from the air and water absorbed by roots, along with light energy, to produce glucose and release oxygen.` },
      { q:`Where does photosynthesis mainly take place in a plant cell?`, ch:[`Mitochondria`,`Nucleus`,`Chloroplasts`,`Ribosomes`], ans:2, exp:`Chloroplasts are the organelles specialized for photosynthesis, containing chlorophyll and the internal membranes needed to capture light energy.` },
      { q:`Which pigment captures light energy for photosynthesis and gives plants their green color?`, ch:[`Melanin`,`Chlorophyll`,`Hemoglobin`,`Carotene`], ans:1, exp:`Chlorophyll is the main pigment in chloroplasts that absorbs light energy, primarily in the red and blue wavelengths, to power photosynthesis.` },
      { q:`Which gas do plants take in from the atmosphere to use in photosynthesis?`, ch:[`Oxygen`,`Nitrogen`,`Carbon dioxide`,`Hydrogen`], ans:2, exp:`Plants absorb carbon dioxide through tiny pores called stomata, using it as a carbon source to build glucose molecules.` },
      { q:`Which gas is released into the atmosphere as a byproduct of photosynthesis?`, ch:[`Carbon dioxide`,`Oxygen`,`Methane`,`Nitrogen`], ans:1, exp:`During photosynthesis, water molecules are split to provide electrons, releasing oxygen gas as a byproduct that is released into the atmosphere.` },
      { q:`What is the source of energy that powers photosynthesis?`, ch:[`Sunlight`,`Heat from the soil`,`Chemical energy from rocks`,`ATP from other cells`], ans:0, exp:`Photosynthesis is powered by light energy, usually from the sun, which chloroplasts capture and convert into chemical energy stored in glucose.` },
      { q:`Photosynthesis can be divided into two main stages: the light-dependent reactions and the:`, ch:[`Krebs cycle`,`Calvin cycle`,`Glycolysis`,`Electron transport only`], ans:1, exp:`The light-dependent reactions capture light energy, and the Calvin cycle (light-independent reactions) uses that energy to build glucose from carbon dioxide.` },
      { q:`Where in the chloroplast do the light-dependent reactions occur?`, ch:[`Stroma`,`Thylakoid membrane`,`Outer membrane`,`Cytoplasm`], ans:1, exp:`The light-dependent reactions occur in the thylakoid membranes, stacked disc-like structures inside the chloroplast that contain chlorophyll.` },
      { q:`Where in the chloroplast does the Calvin cycle take place?`, ch:[`Thylakoid membrane`,`Mitochondrial matrix`,`Stroma`,`Nucleus`], ans:2, exp:`The Calvin cycle occurs in the stroma, the fluid-filled space surrounding the thylakoids, where carbon dioxide is converted into sugar.` },
      { q:`Which molecules made during the light-dependent reactions provide energy to power the Calvin cycle?`, ch:[`ATP and NADPH`,`Glucose and oxygen`,`Carbon dioxide and water`,`DNA and RNA`], ans:0, exp:`The light-dependent reactions produce ATP and NADPH, which supply the energy and electrons needed to convert carbon dioxide into glucose in the Calvin cycle.` },
      { q:`What is the primary sugar product built during photosynthesis?`, ch:[`Fructose`,`Glucose`,`Sucrose`,`Lactose`], ans:1, exp:`Photosynthesis ultimately produces glucose, a simple sugar that the plant can use for energy or convert into starch and other molecules.` },
      { q:`Why is photosynthesis important for most other life on Earth?`, ch:[`It removes all water from the atmosphere`,`It produces oxygen and forms the base of most food chains`,`It only benefits the plant performing it`,`It produces carbon dioxide needed by animals`], ans:1, exp:`Photosynthesis releases the oxygen most organisms need to breathe and produces glucose, which forms the energy base for nearly all food chains.` },
      { q:`Why do most plants appear green to our eyes?`, ch:[`Chlorophyll absorbs green light strongly`,`Chlorophyll reflects green light rather than absorbing it`,`Plants produce green pigment as waste`,`Green light is the only light plants use`], ans:1, exp:`Chlorophyll absorbs red and blue light efficiently but reflects green light, which is why plants appear green to our eyes.` },
    ]
  },
  {
    id:'bb104', cat:'Life Sciences', title:'Cellular Respiration: The Big Picture', diff:'Medium',
    qs:[
      { q:`Which equation best summarizes aerobic cellular respiration?`, ch:[`Carbon dioxide + water -> glucose + oxygen`,`Glucose + oxygen -> carbon dioxide + water + ATP`,`Glucose -> lactic acid`,`ATP -> glucose + oxygen`], ans:1, exp:`Cellular respiration breaks down glucose using oxygen, releasing carbon dioxide and water as byproducts while producing usable energy in the form of ATP.` },
      { q:`What is the main purpose of cellular respiration?`, ch:[`To build new DNA strands`,`To convert energy stored in food into usable ATP energy`,`To produce oxygen for the cell`,`To store excess water`], ans:1, exp:`Cellular respiration converts the chemical energy stored in glucose into ATP, the form of energy cells can directly use to power their activities.` },
      { q:`In eukaryotic cells, where does most of cellular respiration occur?`, ch:[`Nucleus`,`Ribosomes`,`Mitochondria`,`Golgi apparatus`], ans:2, exp:`Mitochondria are the main site of aerobic cellular respiration, where most of the ATP is generated after glucose is partially broken down in the cytoplasm.` },
      { q:`Which gas is required for aerobic (oxygen-using) cellular respiration to occur fully?`, ch:[`Nitrogen`,`Oxygen`,`Hydrogen`,`Chlorine`], ans:1, exp:`Aerobic respiration requires oxygen to fully break down glucose and maximize ATP production; without oxygen, the cell must rely on much less efficient fermentation.` },
      { q:`What are the two main waste products released during aerobic cellular respiration?`, ch:[`Glucose and oxygen`,`Carbon dioxide and water`,`Nitrogen and ATP`, `Lactic acid and ethanol`], ans:1, exp:`As glucose is fully broken down with oxygen, carbon dioxide and water are released as waste products, while the captured energy is stored in ATP.` },
      { q:`Which molecule is the main energy currency produced by cellular respiration?`, ch:[`DNA`,`ATP`,`Glucose`,`Chlorophyll`], ans:1, exp:`ATP (adenosine triphosphate) is the molecule cells use to store and transfer usable energy for their everyday activities.` },
      { q:`What is the name of the first step of cellular respiration, which occurs in the cytoplasm and does not require oxygen?`, ch:[`Glycolysis`,`The Calvin cycle`,`Photosynthesis`,`Transcription`], ans:0, exp:`Glycolysis is the initial breakdown of glucose into two smaller molecules called pyruvate, and it takes place in the cytoplasm without needing oxygen.` },
      { q:`If oxygen is available, what happens to the pyruvate produced by glycolysis?`, ch:[`It is released as a waste gas`,`It enters the mitochondria to be broken down further, producing much more ATP`,`It is converted directly into DNA`,`It leaves the cell immediately`], ans:1, exp:`With oxygen present, pyruvate moves into the mitochondria where it is further broken down, releasing far more ATP than glycolysis alone could produce.` },
      { q:`Fermentation is a process that occurs when a cell:`, ch:[`Has plenty of oxygen available`,`Lacks sufficient oxygen and needs an anaerobic way to keep glycolysis running`,`Wants to build new chloroplasts`,`Is dividing into two new cells`], ans:1, exp:`When oxygen is limited, cells can use fermentation (such as producing lactic acid) to regenerate molecules needed to keep glycolysis going, though it yields far less ATP.` },
      { q:`Compared to fermentation, aerobic cellular respiration produces:`, ch:[`Far less ATP per glucose molecule`,`No ATP at all`,`Far more ATP per glucose molecule`,`The exact same amount of ATP`], ans:2, exp:`Aerobic respiration fully breaks down glucose using oxygen and yields far more ATP per glucose molecule than anaerobic fermentation, which only partially breaks down glucose.` },
      { q:`How are photosynthesis and cellular respiration related?`, ch:[`They are unrelated processes that never interact`,`The products of one process are roughly the reactants of the other`,`Both processes only occur in animal cells`,`Both processes release the same waste gas`], ans:1, exp:`Photosynthesis takes in carbon dioxide and water to make glucose and oxygen, while cellular respiration takes in glucose and oxygen to release carbon dioxide, water, and ATP — the two cycles complement each other.` },
      { q:`Why might a person's muscle cells rely on lactic acid fermentation during intense exercise?`, ch:[`Because muscles never use oxygen`,`Because oxygen delivery cannot keep up with the muscle's energy demand`,`Because fermentation produces more ATP than aerobic respiration`,`Because muscles lack mitochondria`], ans:1, exp:`During intense exercise, oxygen may not reach muscle cells fast enough to meet demand, so cells temporarily rely on lactic acid fermentation to keep producing some ATP.` },
    ]
  },
  {
    id:'bb105', cat:'Life Sciences', title:'DNA Structure & Replication Basics', diff:'Medium',
    qs:[
      { q:`What overall shape does a DNA molecule have?`, ch:[`Single straight strand`,`Double helix`,`Perfect sphere`,`Flat sheet`], ans:1, exp:`DNA is shaped like a double helix, resembling a twisted ladder made of two strands wound around each other.` },
      { q:`What are the individual building blocks of a DNA strand called?`, ch:[`Amino acids`,`Nucleotides`,`Fatty acids`,`Monosaccharides`], ans:1, exp:`DNA is built from repeating units called nucleotides, each made of a sugar, a phosphate group, and a nitrogenous base.` },
      { q:`Which three components make up a single DNA nucleotide?`, ch:[`A sugar, a phosphate group, and a nitrogenous base`,`Two sugars and a protein`,`A lipid, a phosphate, and an amino acid`,`Three nitrogenous bases`], ans:0, exp:`Each nucleotide consists of a deoxyribose sugar, a phosphate group, and one of four nitrogenous bases, linked together to form the DNA strand.` },
      { q:`Which four nitrogenous bases are found in DNA?`, ch:[`Adenine, thymine, cytosine, guanine`,`Adenine, uracil, cytosine, guanine`,`Thymine, glucose, cytosine, guanine`,`Adenine, thymine, ribose, guanine`], ans:0, exp:`DNA contains four nitrogenous bases: adenine (A), thymine (T), cytosine (C), and guanine (G). RNA uses uracil (U) instead of thymine.` },
      { q:`According to base-pairing rules, adenine (A) always pairs with:`, ch:[`Guanine (G)`,`Cytosine (C)`,`Thymine (T)`,`Another adenine (A)`], ans:2, exp:`In DNA, adenine always pairs with thymine (A-T) via two hydrogen bonds, while cytosine pairs with guanine (C-G) via three hydrogen bonds.` },
      { q:`Cytosine (C) always pairs with which base in DNA?`, ch:[`Guanine (G)`,`Thymine (T)`,`Adenine (A)`,`Uracil (U)`], ans:0, exp:`Cytosine pairs specifically with guanine (C-G) through three hydrogen bonds, forming one of the two complementary base pairs in DNA.` },
      { q:`What holds the two strands of the DNA double helix together?`, ch:[`Covalent bonds between sugars`,`Hydrogen bonds between paired bases`,`Ionic bonds between phosphates`,`Peptide bonds between amino acids`], ans:1, exp:`Hydrogen bonds form between complementary base pairs (A-T and C-G) on opposite strands, holding the double helix together while still allowing it to unzip for replication.` },
      { q:`What is the process of copying a DNA molecule called?`, ch:[`Transcription`,`Translation`,`DNA replication`,`Mutation`], ans:2, exp:`DNA replication is the process by which a cell copies its DNA to produce an identical copy before cell division.` },
      { q:`Which enzyme is primarily responsible for unwinding and separating (unzipping) the two strands of the DNA double helix?`, ch:[`DNA polymerase`,`Helicase`,`Ligase`,`RNA polymerase`], ans:1, exp:`Helicase unwinds and separates the two strands of the DNA double helix by breaking the hydrogen bonds between base pairs, allowing replication to begin.` },
      { q:`Which enzyme adds new complementary nucleotides to build a new DNA strand during replication?`, ch:[`Helicase`,`DNA polymerase`,`Ribosome`,`Lysosome`], ans:1, exp:`DNA polymerase reads each existing (template) strand and adds the correctly paired nucleotides to build a new complementary strand.` },
      { q:`Why is DNA replication described as "semiconservative"?`, ch:[`Because both new DNA molecules are entirely new`,`Because each new DNA molecule contains one original strand and one newly made strand`,`Because only half of the DNA gets copied`,`Because DNA replication only happens half the time`], ans:1, exp:`Semiconservative replication means each resulting DNA molecule keeps one original (parent) strand and pairs it with one newly synthesized strand.` },
      { q:`When does DNA replication typically occur in the cell cycle?`, ch:[`After cell division is complete`,`During protein digestion`,`Before a cell divides, so each new cell gets a full copy of DNA`,`Only in dead cells`], ans:2, exp:`DNA replication occurs before a cell divides, ensuring that each resulting daughter cell receives a complete, identical copy of the genetic material.` },
      { q:`What is the main function of DNA in a cell?`, ch:[`To provide structural support like a skeleton`,`To store genetic instructions used to build proteins and pass on traits`,`To directly digest food molecules`,`To produce light energy`], ans:1, exp:`DNA stores the genetic instructions (in the sequence of its bases) that cells use to build proteins and that are passed from parent to offspring.` },
    ]
  },
  {
    id:'bb106', cat:'Life Sciences', title:'Heredity & Punnett Squares', diff:'Medium',
    qs:[
      { q:`Who is often called the "father of genetics" for his pea plant experiments?`, ch:[`Charles Darwin`,`Gregor Mendel`,`James Watson`,`Louis Pasteur`], ans:1, exp:`Gregor Mendel studied inheritance patterns in pea plants in the 1800s, establishing the basic principles of how traits are passed from parents to offspring.` },
      { q:`What is an allele?`, ch:[`A different version or form of a gene`,`A type of cell organelle`,`The physical trait itself`,`A chromosome found only in males`], ans:0, exp:`An allele is one of two or more alternative versions of a gene, such as the alleles for brown eyes versus blue eyes.` },
      { q:`An organism's genotype refers to its:`, ch:[`Physical, observable appearance`,`Genetic makeup (the alleles it carries)`,`Diet and environment`,`Behavior patterns`], ans:1, exp:`Genotype describes the specific combination of alleles an organism has for a trait, such as being BB, Bb, or bb.` },
      { q:`An organism's phenotype refers to its:`, ch:[`Genetic makeup only`,`Number of chromosomes`,`Observable physical trait or characteristic`,`DNA sequence only`], ans:2, exp:`Phenotype is the observable expression of a trait, such as actual eye color or flower color, resulting from the genotype and sometimes environmental influences.` },
      { q:`An organism that is homozygous for a trait has:`, ch:[`Two different alleles for that trait`,`Two identical alleles for that trait`,`No alleles for that trait`,`Three alleles for that trait`], ans:1, exp:`Homozygous means an organism carries two identical alleles for a given gene, such as BB (homozygous dominant) or bb (homozygous recessive).` },
      { q:`An organism that is heterozygous for a trait has:`, ch:[`Two identical alleles`,`Two different alleles`,`No genetic material`,`Only a dominant allele present`], ans:1, exp:`Heterozygous means an organism carries two different alleles for a gene, such as Bb, where B is dominant and b is recessive.` },
      { q:`For a recessive trait to be expressed in the phenotype, an organism generally must be:`, ch:[`Heterozygous for that gene`,`Homozygous dominant for that gene`,`Homozygous recessive for that gene`,`Missing that gene entirely`], ans:2, exp:`A recessive trait is typically only expressed when an organism has two copies of the recessive allele (homozygous recessive), since a single dominant allele would mask it.` },
      { q:`In a cross between two heterozygous parents (Bb x Bb), what percentage of offspring is expected to be homozygous recessive (bb)?`, ch:[`0%`,`25%`,`50%`,`100%`], ans:1, exp:`A Bb x Bb cross produces a classic 1:2:1 genotype ratio (BB : Bb : bb), meaning 25% of offspring are expected to be homozygous recessive (bb).` },
      { q:`In a cross between a homozygous dominant parent (BB) and a homozygous recessive parent (bb), what genotype do all offspring have?`, ch:[`All BB`,`All bb`,`All Bb (heterozygous)`,`Half BB and half bb`], ans:2, exp:`Every offspring receives one B allele from the BB parent and one b allele from the bb parent, so all offspring are heterozygous (Bb).` },
      { q:`What tool is commonly used to predict the possible genotype combinations of offspring from a genetic cross?`, ch:[`Punnett square`,`Microscope`,`Periodic table`,`Food chain diagram`], ans:0, exp:`A Punnett square is a grid used to visually organize and predict the possible allele combinations, and their probabilities, resulting from a genetic cross.` },
      { q:`If brown eyes (B) are dominant over blue eyes (b), what phenotype ratio is expected from a Bb x bb cross?`, ch:[`All brown eyes`,`All blue eyes`,`1 brown : 1 blue`,`3 brown : 1 blue`], ans:2, exp:`A Bb x bb cross yields offspring genotypes of Bb and bb in a 1:1 ratio, so half the offspring (Bb) show brown eyes and half (bb) show blue eyes.` },
      { q:`By convention, when writing a genotype, a capital letter (like B) typically represents:`, ch:[`The recessive allele`,`The dominant allele`,`A chromosome`,`An entire gene pool`], ans:1, exp:`In standard genetics notation, a capital letter represents the dominant allele, while the corresponding lowercase letter represents the recessive allele.` },
    ]
  },
  {
    id:'bb107', cat:'Life Sciences', title:'Classification of Living Things', diff:'Easy',
    qs:[
      { q:`What is the scientific study of classifying and naming organisms called?`, ch:[`Ecology`,`Taxonomy`,`Physiology`,`Genetics`], ans:1, exp:`Taxonomy is the branch of biology focused on identifying, naming, and classifying organisms into organized groups based on shared characteristics.` },
      { q:`Who developed the modern two-name classification system still used today?`, ch:[`Charles Darwin`,`Carl Linnaeus`,`Gregor Mendel`,`Rosalind Franklin`], ans:1, exp:`Carl Linnaeus developed binomial nomenclature in the 1700s, the two-name naming system that classifies organisms by genus and species.` },
      { q:`A scientific (binomial) name for a species consists of which two parts?`, ch:[`Kingdom and phylum`,`Genus and species`,`Class and order`,`Family and domain`], ans:1, exp:`Binomial nomenclature gives each organism a two-part Latin name: the genus name first, followed by the specific species name, such as Homo sapiens.` },
      { q:`Which classification level is the broadest, containing the most organisms, among Kingdom, Order, Genus, and Species?`, ch:[`Species`,`Genus`,`Order`,`Kingdom`], ans:3, exp:`Kingdom is the broadest of these levels, grouping large numbers of diverse organisms, while Species is the narrowest, most specific level.` },
      { q:`Mushrooms and molds belong to which kingdom?`, ch:[`Plantae`,`Animalia`,`Fungi`,`Bacteria`], ans:2, exp:`Mushrooms and molds are classified in kingdom Fungi, organisms that absorb nutrients from their environment rather than making their own food or ingesting it like animals.` },
      { q:`Simple, single-celled organisms without a nucleus, like most bacteria, are classified into which type of kingdom?`, ch:[`Plantae`,`Animalia`,`Fungi`,`Bacteria (prokaryotes)`], ans:3, exp:`Bacteria are prokaryotic organisms, lacking a nucleus, and are grouped into their own kingdom(s) separate from plants, animals, fungi, and protists.` },
      { q:`Multicellular organisms that photosynthesize and have cell walls made of cellulose belong to which kingdom?`, ch:[`Animalia`,`Fungi`,`Plantae`,`Monera`], ans:2, exp:`Kingdom Plantae includes multicellular, photosynthetic organisms with cellulose cell walls, such as trees, grasses, and flowers.` },
      { q:`Multicellular organisms that must consume food (cannot make their own) and lack cell walls belong to which kingdom?`, ch:[`Animalia`,`Plantae`,`Fungi`,`Protista`], ans:0, exp:`Kingdom Animalia includes multicellular organisms that are heterotrophic (must eat other organisms for energy) and lack rigid cell walls.` },
      { q:`Which term best defines a "species"?`, ch:[`Any organism living in the same habitat`,`A group of organisms that can interbreed and produce fertile offspring`,`Organisms that share the same diet`,`Organisms found on the same continent`], ans:1, exp:`A species is generally defined as a group of organisms capable of interbreeding in nature and producing fertile offspring.` },
      { q:`Among the classification levels Kingdom, Phylum, Class, Order, Family, Genus, and Species, which is the most specific?`, ch:[`Kingdom`,`Phylum`,`Family`,`Species`], ans:3, exp:`Species is the most specific, narrowest classification level, referring to a single distinct type of organism, while Kingdom is the broadest.` },
      { q:`Literally translated, "binomial nomenclature" means:`, ch:[`Single-name system`,`Two-name naming system`,`Color-based naming system`,`Random naming system`], ans:1, exp:`"Binomial" means two names, and "nomenclature" means naming system, referring to the genus-plus-species naming convention for organisms.` },
      { q:`Why is a standardized scientific classification system useful?`, ch:[`It has no real scientific value`,`It shows evolutionary relationships and avoids confusion caused by different common names`,`It replaces the need to study organisms at all`,`It only matters for naming pets`], ans:1, exp:`Scientific classification groups organisms by shared, often evolutionarily related traits, and avoids the confusion of common names that vary by region or language.` },
    ]
  },
  {
    id:'bb108', cat:'Life Sciences', title:'Ecosystems & Food Chains', diff:'Easy',
    qs:[
      { q:`What is an ecosystem?`, ch:[`Only the living organisms in an area`,`A community of living organisms interacting with each other and their physical environment`,`A single population of one species`,`A man-made habitat only`], ans:1, exp:`An ecosystem includes all the living organisms (biotic factors) in an area along with the nonliving physical environment (abiotic factors, like water and sunlight) they interact with.` },
      { q:`What is a producer in an ecosystem?`, ch:[`An organism that eats other organisms for energy`,`An organism that makes its own food, usually via photosynthesis`,`An organism that only breaks down dead matter`,`An organism with no role in the food chain`], ans:1, exp:`Producers, such as plants and algae, are autotrophs that make their own food, usually through photosynthesis, forming the base of most food chains.` },
      { q:`What is a consumer in an ecosystem?`, ch:[`An organism that makes its own food`,`An organism that obtains energy by eating other organisms`,`A nonliving part of the environment`,`A type of decomposer only`], ans:1, exp:`Consumers are heterotrophs that must eat other organisms (producers or other consumers) to obtain energy, since they cannot make their own food.` },
      { q:`What role do decomposers play in an ecosystem?`, ch:[`They make food using sunlight`,`They break down dead organisms and waste, recycling nutrients back into the environment`,`They only hunt live prey`,`They convert oxygen into carbon dioxide exclusively`], ans:1, exp:`Decomposers, such as fungi and certain bacteria, break down dead organic matter, returning nutrients to the soil so they can be reused by producers.` },
      { q:`What does a food chain show?`, ch:[`A random collection of unrelated organisms`,`A simple, linear sequence showing how energy passes from one organism to the next`,`Only where organisms live`,`The exact number of organisms in an area`], ans:1, exp:`A food chain is a simple linear diagram showing the transfer of energy as one organism is eaten by the next, starting typically with a producer.` },
      { q:`How does a food web differ from a single food chain?`, ch:[`A food web has no producers`,`A food web is a network of interconnected, overlapping food chains`,`A food web only includes decomposers`,`A food web can only include two organisms`], ans:1, exp:`A food web shows the more realistic, interconnected feeding relationships among many organisms, combining multiple overlapping food chains.` },
      { q:`According to the general "10% rule," roughly how much energy is passed from one trophic level to the next?`, ch:[`100%`,`50%`,`10%`,`0%`], ans:2, exp:`On average, only about 10% of the energy at one trophic level is transferred to the next level; the rest is lost mainly as heat through life processes.` },
      { q:`Which trophic level in an energy pyramid generally contains the most available energy?`, ch:[`Top predators`,`Secondary consumers`,`Producers (the bottom level)`,`Tertiary consumers`], ans:2, exp:`Producers form the base of the energy pyramid and contain the most total energy, since energy decreases at each successive trophic level.` },
      { q:`A primary consumer is an organism that:`, ch:[`Eats only other consumers`,`Eats producers directly`,`Makes its own food`,`Decomposes dead matter only`], ans:1, exp:`Primary consumers, often herbivores, feed directly on producers, making them the second trophic level in a food chain.` },
      { q:`An organism that eats only plants is called a(n):`, ch:[`Carnivore`,`Omnivore`,`Herbivore`,`Decomposer`], ans:2, exp:`Herbivores are consumers that eat only plant material (producers) for energy.` },
      { q:`An organism that eats both plants and animals is called a(n):`, ch:[`Herbivore`,`Omnivore`,`Producer`,`Decomposer`], ans:1, exp:`Omnivores consume both plant and animal material, giving them a varied diet that spans multiple trophic levels.` },
      { q:`Why does the total available energy decrease at each higher trophic level in an energy pyramid?`, ch:[`Energy is created at each level`,`Energy is lost mainly as heat through metabolic processes at each level`,`Organisms at higher levels do not use any energy`,`Producers absorb energy back from consumers`], ans:1, exp:`As organisms use energy for life processes like movement and growth, much of it is released as heat, so less usable energy remains to pass on to the next trophic level.` },
    ]
  },
  {
    id:'bb109', cat:'Life Sciences', title:'Evolution & Natural Selection Basics', diff:'Medium',
    qs:[
      { q:`Who is best known for proposing the theory of evolution by natural selection?`, ch:[`Gregor Mendel`,`Charles Darwin`,`Louis Pasteur`,`Carl Linnaeus`], ans:1, exp:`Charles Darwin proposed the theory of evolution by natural selection in the 1800s, based largely on observations made during his voyage on the HMS Beagle.` },
      { q:`Natural selection is best described as the process by which:`, ch:[`All individuals in a population survive equally`,`Organisms with traits better suited to their environment tend to survive and reproduce more successfully`,`Organisms choose which traits to pass on`,`Species never change over time`], ans:1, exp:`Natural selection favors individuals whose inherited traits give them an advantage in survival and reproduction, making those traits more common in future generations.` },
      { q:`The phrase "survival of the fittest" refers to the idea that:`, ch:[`Only the physically strongest organisms exist`,`Organisms best suited to their environment are more likely to survive and reproduce`,`All organisms are equally fit for every environment`,`Fitness has nothing to do with reproduction`], ans:1, exp:`In evolutionary terms, "fittest" means best suited to the current environment, not necessarily strongest; these organisms are more likely to survive and pass on their traits.` },
      { q:`An adaptation is best defined as:`, ch:[`Any random behavior an organism performs once`,`An inherited trait that helps an organism survive and reproduce in its environment`,`A trait acquired during an organism's lifetime that is passed to offspring`,`A trait with no effect on survival`], ans:1, exp:`Adaptations are inherited traits, shaped by natural selection over generations, that improve an organism's ability to survive and reproduce in its specific environment.` },
      { q:`What must be present within a population for natural selection to act upon it?`, ch:[`Identical genes in every individual`,`Genetic variation among individuals`,`A constant, unchanging environment`,`Unlimited resources`], ans:1, exp:`Natural selection requires genetic variation, differences among individuals in a population, so that some variants can be favored over others depending on the environment.` },
      { q:`What is a mutation?`, ch:[`A learned behavior`,`A change in an organism's DNA sequence`,`A type of ecosystem`,`A dominant allele only`], ans:1, exp:`A mutation is a change in the DNA sequence, which can create new alleles and is an important original source of genetic variation in a population.` },
      { q:`During the Industrial Revolution, dark-colored peppered moths became more common in polluted areas mainly because:`, ch:[`They tasted better to predators`,`Their dark color provided better camouflage against soot-darkened trees, reducing predation`,`They reproduced faster regardless of color`,`Light-colored moths went extinct from pollution directly`], ans:1, exp:`Soot from factories darkened tree bark, so dark moths were better camouflaged from predators than light moths, giving dark moths a survival advantage — a classic example of natural selection.` },
      { q:`What is speciation?`, ch:[`The extinction of a species`,`The process by which new species form over time`,`The classification of a species' name`,`A single organism changing species during its lifetime`], ans:1, exp:`Speciation is the evolutionary process by which populations accumulate enough differences over time to become distinct, separate species.` },
      { q:`In evolutionary biology, "fitness" refers to an organism's:`, ch:[`Physical strength alone`,`Ability to survive and successfully reproduce, passing genes to the next generation`,`Speed compared to other species`,`Size relative to its habitat`], ans:1, exp:`Fitness measures reproductive success — how well an organism survives and passes its genes on to offspring — not simply physical strength or size.` },
      { q:`Fossils, comparative anatomy, and DNA similarities between species are all examples of:`, ch:[`Evidence supporting the theory of evolution`,`Proof that evolution does not occur`,`Random, unrelated observations`,`Evidence used only in classification, unrelated to evolution`], ans:0, exp:`Fossils showing gradual change, similar anatomical structures across species, and shared DNA sequences all provide strong evidence supporting the theory of evolution.` },
      { q:`Artificial selection differs from natural selection because in artificial selection:`, ch:[`Nature alone determines which traits survive`,`Humans choose which organisms breed based on desired traits`,`No traits are inherited`,`Mutations cannot occur`], ans:1, exp:`In artificial selection, humans intentionally breed organisms, such as crops or dogs, that display desired traits, rather than the environment naturally selecting for survival advantages.` },
      { q:`Which statement is most accurate regarding evolution?`, ch:[`Individual organisms evolve significant new traits during their own lifetime`,`Populations evolve over many generations as the frequency of traits changes`,`Evolution only affects a single organism at a time`,`Evolution requires organisms to want to change`], ans:1, exp:`Evolution is a change in a population's inherited traits over many generations, not a change that occurs within a single individual's lifetime.` },
    ]
  },
  {
    id:'bb110', cat:'Life Sciences', title:'The Human Body: Organ Systems Overview', diff:'Easy',
    qs:[
      { q:`What is an organ?`, ch:[`A single cell performing one function`,`A structure made of two or more types of tissue working together to perform a function`,`A group of unrelated cells`,`Another name for an organ system`], ans:1, exp:`An organ, such as the heart or stomach, is made of different tissue types working together to carry out a specific job in the body.` },
      { q:`What is an organ system?`, ch:[`A single organ working alone`,`A group of organs working together to carry out a broad body function`,`A type of cell`,`A single tissue type`], ans:1, exp:`An organ system is a group of organs that work together to perform a major function, such as the digestive system breaking down food.` },
      { q:`Which organ system is primarily responsible for pumping blood throughout the body?`, ch:[`Respiratory system`,`Circulatory system`,`Digestive system`,`Skeletal system`], ans:1, exp:`The circulatory system, centered on the heart and blood vessels, is responsible for pumping blood and transporting oxygen, nutrients, and wastes throughout the body.` },
      { q:`Which organ system is primarily responsible for gas exchange (bringing in oxygen and removing carbon dioxide)?`, ch:[`Respiratory system`,`Muscular system`,`Endocrine system`,`Immune system`], ans:0, exp:`The respiratory system, including the lungs, allows the body to take in oxygen and release carbon dioxide through breathing.` },
      { q:`Which organ system breaks down food into nutrients the body can absorb and use?`, ch:[`Circulatory system`,`Nervous system`,`Digestive system`,`Skeletal system`], ans:2, exp:`The digestive system, including the stomach and intestines, mechanically and chemically breaks down food so nutrients can be absorbed into the bloodstream.` },
      { q:`Which organ system filters waste products out of the blood and produces urine?`, ch:[`Excretory (urinary) system`,`Muscular system`,`Respiratory system`,`Endocrine system`], ans:0, exp:`The excretory (urinary) system, centered on the kidneys, filters waste products and excess substances from the blood, forming urine to be eliminated.` },
      { q:`Which organ system provides structural support, protects internal organs, and includes bones?`, ch:[`Skeletal system`,`Muscular system`,`Nervous system`,`Digestive system`], ans:0, exp:`The skeletal system, made of bones, provides the body's structural framework, protects vital organs, and works with muscles to allow movement.` },
      { q:`Which organ system allows the body to move by contracting and relaxing?`, ch:[`Skeletal system`,`Muscular system`,`Endocrine system`,`Immune system`], ans:1, exp:`The muscular system is made of tissues that contract and relax, working with the skeletal system to produce body movement.` },
      { q:`Which organ system coordinates rapid body responses using electrical signals?`, ch:[`Nervous system`,`Endocrine system`,`Digestive system`,`Excretory system`], ans:0, exp:`The nervous system, including the brain, spinal cord, and nerves, sends fast electrical signals to coordinate and control body activities.` },
      { q:`Which organ system uses hormones released into the blood to regulate body functions more slowly?`, ch:[`Endocrine system`,`Nervous system`,`Skeletal system`,`Respiratory system`], ans:0, exp:`The endocrine system releases hormones (chemical messengers) into the bloodstream to regulate body processes like growth and metabolism, generally acting more slowly than the nervous system.` },
      { q:`Which organ system defends the body against pathogens like bacteria and viruses?`, ch:[`Muscular system`,`Immune system`,`Skeletal system`,`Digestive system`], ans:1, exp:`The immune system includes cells and organs that identify and destroy harmful pathogens to protect the body from disease.` },
      { q:`Which of the following correctly lists levels of biological organization from simplest to most complex?`, ch:[`Organism, organ system, organ, tissue, cell`,`Cell, tissue, organ, organ system, organism`,`Tissue, cell, organism, organ, organ system`,`Organ, cell, tissue, organism, organ system`], ans:1, exp:`Biological organization builds from the smallest unit up: cells combine to form tissues, tissues form organs, organs form organ systems, and organ systems make up the whole organism.` },
      { q:`Which organ system includes the skin and functions as the body's protective outer barrier?`, ch:[`Integumentary system`,`Circulatory system`,`Nervous system`,`Endocrine system`], ans:0, exp:`The integumentary system, including skin, hair, and nails, forms a protective barrier against pathogens, injury, and water loss.` },
    ]
  },
  {
    id:'bb111', cat:'Life Sciences', title:'The Circulatory System Basics', diff:'Medium',
    qs:[
      { q:`What is the main function of the circulatory system?`, ch:[`To break down food into nutrients`,`To transport blood carrying oxygen, nutrients, and wastes throughout the body`,`To coordinate electrical signals in the body`,`To filter air before it enters the lungs`], ans:1, exp:`The circulatory system moves blood throughout the body, delivering oxygen and nutrients to cells and carrying away waste products like carbon dioxide.` },
      { q:`Which organ acts as the main pump of the circulatory system?`, ch:[`Liver`,`Heart`,`Kidney`,`Lung`], ans:1, exp:`The heart is a muscular organ that contracts rhythmically to pump blood through the blood vessels to the rest of the body.` },
      { q:`How many chambers does a typical human heart have?`, ch:[`Two`,`Three`,`Four`,`Six`], ans:2, exp:`The human heart has four chambers: two upper chambers called atria and two lower chambers called ventricles.` },
      { q:`What are the two upper chambers of the heart called?`, ch:[`Ventricles`,`Atria`,`Valves`,`Capillaries`], ans:1, exp:`The atria (singular: atrium) are the two upper chambers of the heart that receive blood returning from the body and lungs.` },
      { q:`What are the two lower, more muscular chambers of the heart called?`, ch:[`Atria`,`Ventricles`,`Aortas`,`Veins`], ans:1, exp:`The ventricles are the two lower chambers of the heart; they are more muscular than the atria because they pump blood out to the lungs and the rest of the body.` },
      { q:`Which type of blood vessel generally carries blood away from the heart?`, ch:[`Veins`,`Capillaries`,`Arteries`,`Lymph vessels`], ans:2, exp:`Arteries are blood vessels that carry blood away from the heart, usually under higher pressure, toward the lungs or body tissues.` },
      { q:`Which type of blood vessel generally carries blood back toward the heart?`, ch:[`Arteries`,`Veins`,`Capillaries`,`Bronchioles`], ans:1, exp:`Veins are blood vessels that carry blood back toward the heart, often containing valves to help prevent backflow.` },
      { q:`Which are the smallest blood vessels, where oxygen, nutrients, and wastes are exchanged with body tissues?`, ch:[`Arteries`,`Veins`,`Capillaries`,`Aorta`], ans:2, exp:`Capillaries are tiny, thin-walled vessels connecting arteries and veins, and their thin walls allow gases and nutrients to diffuse between the blood and surrounding tissue cells.` },
      { q:`What is the main function of red blood cells?`, ch:[`Fighting infection`,`Clotting blood`,`Carrying oxygen throughout the body using hemoglobin`,`Digesting nutrients`], ans:2, exp:`Red blood cells contain hemoglobin, a protein that binds oxygen in the lungs and releases it to tissues throughout the body.` },
      { q:`What is the main function of white blood cells?`, ch:[`Carrying oxygen`,`Fighting infection and defending the body against pathogens`,`Clotting wounds`,`Transporting hormones only`], ans:1, exp:`White blood cells are part of the immune system and help defend the body by identifying and destroying pathogens like bacteria and viruses.` },
      { q:`What is the main function of platelets in the blood?`, ch:[`Carrying oxygen`,`Producing antibodies`,`Helping blood clot to stop bleeding`,`Transporting carbon dioxide`], ans:2, exp:`Platelets are small cell fragments that help form blood clots at the site of an injury, preventing excessive bleeding.` },
      { q:`What is the straw-colored liquid portion of blood called, which carries blood cells and dissolved substances?`, ch:[`Plasma`,`Serum only`,`Lymph`,`Cytoplasm`], ans:0, exp:`Plasma is the liquid component of blood, mostly water, that carries blood cells, nutrients, hormones, and waste products throughout the body.` },
      { q:`Which side of the heart pumps oxygen-poor blood toward the lungs?`, ch:[`Left side`,`Right side`,`Top only`,`Bottom only`], ans:1, exp:`The right side of the heart receives oxygen-poor blood from the body and pumps it to the lungs, where it picks up fresh oxygen.` },
      { q:`Which side of the heart pumps oxygen-rich blood out to the rest of the body?`, ch:[`Right side`,`Left side`,`Neither side`,`Both sides equally pump oxygen-poor blood`], ans:1, exp:`The left side of the heart receives oxygen-rich blood from the lungs and pumps it out through the aorta to the rest of the body.` },
    ]
  },
  {
    id:'bb112', cat:'Life Sciences', title:'The Nervous System Basics', diff:'Medium',
    qs:[
      { q:`What is the basic functional cell of the nervous system?`, ch:[`Red blood cell`,`Neuron`,`Osteocyte`,`Epithelial cell`], ans:1, exp:`Neurons are specialized cells that transmit electrical and chemical signals, forming the basic building blocks of the nervous system.` },
      { q:`Which two structures make up the central nervous system (CNS)?`, ch:[`Heart and lungs`,`Brain and spinal cord`,`Nerves in the arms and legs`,`Skin and muscles`], ans:1, exp:`The central nervous system consists of the brain and spinal cord, which process information and coordinate the body's responses.` },
      { q:`The peripheral nervous system mainly consists of:`, ch:[`Only the brain`,`Only the spinal cord`,`Nerves that connect the brain and spinal cord to the rest of the body`,`Bones and muscles`], ans:2, exp:`The peripheral nervous system includes all the nerves outside the brain and spinal cord, connecting the central nervous system to muscles, organs, and sensory receptors.` },
      { q:`What is the function of a neuron's dendrites?`, ch:[`To receive signals from other neurons`,`To produce new blood cells`,`To digest nutrients`,`To store long-term memories directly`], ans:0, exp:`Dendrites are branch-like extensions of a neuron that receive incoming signals from other neurons and relay them toward the cell body.` },
      { q:`What is the function of a neuron's axon?`, ch:[`To receive signals only`,`To transmit an electrical signal away from the cell body toward other cells`,`To produce hormones`,`To filter blood`], ans:1, exp:`The axon is a long, thin projection of a neuron that carries the electrical signal away from the cell body toward the next neuron or target cell.` },
      { q:`What is a synapse?`, ch:[`The center of the neuron's nucleus`,`The junction where a signal passes from one neuron to another (or to another cell)`,`A type of muscle tissue`,`A bone in the skull`], ans:1, exp:`A synapse is the small gap between two neurons (or a neuron and another cell) where a signal is transmitted, usually using chemical messengers.` },
      { q:`What are the chemical messengers that carry signals across a synapse called?`, ch:[`Hormones only`,`Neurotransmitters`,`Antibodies`,`Enzymes only`], ans:1, exp:`Neurotransmitters are chemicals released by a neuron that cross the synapse and bind to receptors on the next cell, transmitting the signal.` },
      { q:`What is the brain's general role in the nervous system?`, ch:[`It only pumps blood`,`It acts as the body's main control center, processing and interpreting information`,`It only digests food`,`It has no role in decision-making`], ans:1, exp:`The brain is the central processing and control center of the nervous system, interpreting sensory information and directing the body's responses.` },
      { q:`What is the main role of the spinal cord?`, ch:[`It has no connection to the brain`,`It serves as a pathway for signals between the brain and the rest of the body, and controls some reflexes`,`It only stores memories`,`It produces digestive enzymes`], ans:1, exp:`The spinal cord relays signals between the brain and the rest of the body and can also control certain fast, automatic reflex responses on its own.` },
      { q:`What is a reflex?`, ch:[`A slow, carefully considered decision`,`A rapid, automatic response to a stimulus that often does not require conscious brain processing`,`A type of long-term memory`,`A voluntary muscle movement planned in advance`], ans:1, exp:`A reflex is a fast, automatic, involuntary response to a stimulus, such as pulling your hand away from something hot, often processed quickly through the spinal cord.` },
      { q:`Which part of the brain is mainly responsible for coordinating balance and muscle coordination?`, ch:[`Cerebrum`,`Cerebellum`,`Spinal cord`,`Pancreas`], ans:1, exp:`The cerebellum, located at the back of the brain, coordinates balance, posture, and precise muscle movements.` },
      { q:`Which part of the brain is responsible for higher-level thinking, voluntary movement, and processing sensory information?`, ch:[`Cerebellum`,`Cerebrum (cerebral cortex)`,`Spinal cord`,`Brainstem only`], ans:1, exp:`The cerebrum, particularly its outer layer called the cerebral cortex, handles complex functions like thinking, voluntary movement, and interpreting sensory input.` },
      { q:`How do sensory neurons and motor neurons differ?`, ch:[`Sensory neurons carry signals to the central nervous system; motor neurons carry signals away from it to muscles and glands`,`There is no functional difference between them`,`Motor neurons only exist in the brain`,`Sensory neurons only control heartbeat`], ans:0, exp:`Sensory neurons carry information from the body's receptors toward the central nervous system, while motor neurons carry commands away from the central nervous system to muscles and glands.` },
    ]
  },
  {
    id:'bb113', cat:'Life Sciences', title:'The Immune System Basics', diff:'Medium',
    qs:[
      { q:`What is the main function of the immune system?`, ch:[`To digest food`,`To defend the body against pathogens like bacteria and viruses`,`To pump blood throughout the body`,`To produce sound waves for hearing`], ans:1, exp:`The immune system's primary job is to detect and defend the body against harmful invaders, including bacteria, viruses, and other pathogens.` },
      { q:`What is a pathogen?`, ch:[`A helpful gut bacterium`,`A disease-causing organism or agent, such as certain bacteria or viruses`,`A type of white blood cell`,`A vitamin needed for growth`], ans:1, exp:`A pathogen is any organism or agent, such as a virus, bacterium, or fungus, capable of causing disease in a host.` },
      { q:`What is generally considered the body's first line of defense against pathogens?`, ch:[`Antibodies`,`Physical barriers like the skin and mucous membranes`,`White blood cells only`,`Fever only`], ans:1, exp:`Physical barriers such as the skin and mucous membranes form the first line of defense, physically blocking most pathogens from entering the body.` },
      { q:`What is the general role of white blood cells (leukocytes) in the immune system?`, ch:[`To carry oxygen throughout the body`,`To identify and help destroy pathogens`,`To clot blood at a wound`,`To digest fats in the small intestine`], ans:1, exp:`White blood cells are the immune system's main cellular defenders, recognizing and helping to eliminate pathogens and infected cells.` },
      { q:`What is a phagocyte?`, ch:[`A type of red blood cell`,`A white blood cell that engulfs and digests pathogens or debris`,`A protein that clots blood`,`A hormone that regulates metabolism`], ans:1, exp:`A phagocyte is a type of white blood cell that surrounds, engulfs, and breaks down pathogens or cellular debris, a process called phagocytosis.` },
      { q:`What is an antibody?`, ch:[`A type of pathogen`,`A protein produced by the immune system that recognizes and binds to a specific antigen`,`A muscle protein`,`A carbohydrate found in food`], ans:1, exp:`Antibodies are Y-shaped proteins produced by immune cells that specifically recognize and bind to antigens, helping to mark or neutralize pathogens.` },
      { q:`What is an antigen?`, ch:[`A molecule, often on a pathogen's surface, that triggers an immune response`,`A type of antibiotic medication`,`A red blood cell component`,`A digestive enzyme`], ans:0, exp:`An antigen is a molecule, frequently found on the surface of a pathogen, that the immune system recognizes as foreign and responds to.` },
      { q:`Lymphocytes, a key type of white blood cell in adaptive immunity, are mainly divided into which two types?`, ch:[`Red cells and platelets`,`B cells and T cells`,`Nerve cells and muscle cells`,`Enzymes and hormones`], ans:1, exp:`Lymphocytes are divided into B cells, which produce antibodies, and T cells, which include helper cells that coordinate the immune response and cytotoxic cells that destroy infected cells.` },
      { q:`What is the main function of B cells?`, ch:[`To directly digest pathogens`,`To produce antibodies that target specific antigens`,`To transport oxygen`,`To contract and cause movement`], ans:1, exp:`B cells are lymphocytes that, once activated, produce large quantities of antibodies specifically designed to bind a particular antigen.` },
      { q:`What is a vaccine designed to do?`, ch:[`Cause a severe version of the disease`,`Stimulate the immune system to build protective memory against a pathogen without causing full-blown disease`,`Immediately cure an existing infection`,`Replace the need for white blood cells`], ans:1, exp:`Vaccines expose the immune system to a harmless piece or weakened form of a pathogen, prompting it to build memory cells that can respond quickly if the real pathogen is encountered later.` },
      { q:`What is immunological memory?`, ch:[`The immune system's inability to recognize repeat infections`,`The immune system's ability to respond faster and more strongly upon a second exposure to the same pathogen`,`A type of short-term memory in the brain`,`The process of forgetting past infections`], ans:1, exp:`After an initial exposure to a pathogen, memory cells remain in the body, allowing a much faster and stronger immune response if that same pathogen is encountered again.` },
      { q:`Inflammation, marked by redness, heat, and swelling, is best described as:`, ch:[`A sign the immune system has failed`,`A localized response to injury or infection that helps fight pathogens and promote healing`,`A permanent condition with no purpose`,`A process that only occurs in plants`], ans:1, exp:`Inflammation is a protective response in which increased blood flow and immune cell activity help fight infection and begin the healing process at the site of injury.` },
      { q:`How can a fever help the body fight infection?`, ch:[`It has no effect on pathogens`,`Elevated body temperature can slow pathogen reproduction and enhance certain immune responses`,`It directly destroys all white blood cells`,`It stops the heart from pumping blood`], ans:1, exp:`A moderate fever can slow the growth and reproduction of many pathogens while helping to enhance the activity of certain immune cells, aiding the body's defense.` },
    ]
  },
  {
    id:'bb114', cat:'Life Sciences', title:'Human Nutrition & Digestion Basics', diff:'Easy',
    qs:[
      { q:`What is digestion?`, ch:[`The process of breathing in oxygen`,`The breakdown of food into smaller molecules the body can absorb and use`,`The filtering of blood by the kidneys`,`The production of hormones`], ans:1, exp:`Digestion is the mechanical and chemical process of breaking large food molecules into smaller nutrients that the body can absorb and use for energy and growth.` },
      { q:`Which three nutrients are considered the main macronutrients that provide the body with energy?`, ch:[`Carbohydrates, proteins, and fats`,`Vitamins, minerals, and water`,`Water, fiber, and oxygen`,`Iron, calcium, and sodium`], ans:0, exp:`Carbohydrates, proteins, and fats are called macronutrients because the body needs them in relatively large amounts, and each can supply energy (measured in calories).` },
      { q:`Where does chemical digestion of food typically begin?`, ch:[`Stomach`,`Small intestine`,`Mouth`,`Large intestine`], ans:2, exp:`Digestion begins in the mouth, where chewing physically breaks down food and salivary enzymes begin chemical digestion.` },
      { q:`Which enzyme, found in saliva, begins breaking down starch in the mouth?`, ch:[`Amylase`,`Pepsin`,`Lipase`,`Trypsin`], ans:0, exp:`Salivary amylase is an enzyme in saliva that begins breaking down starch (a complex carbohydrate) into smaller sugar molecules while food is still in the mouth.` },
      { q:`Which organ churns food and mixes it with acid and digestive enzymes?`, ch:[`Liver`,`Stomach`,`Large intestine`,`Pancreas`], ans:1, exp:`The stomach churns food and mixes it with hydrochloric acid and digestive enzymes like pepsin, breaking food down further and beginning protein digestion.` },
      { q:`Which organ is the primary site where most nutrients are absorbed into the bloodstream?`, ch:[`Stomach`,`Large intestine`,`Small intestine`,`Esophagus`], ans:2, exp:`The small intestine, with its large surface area created by finger-like projections called villi, is the main site where digested nutrients are absorbed into the blood.` },
      { q:`What is the main function of the large intestine?`, ch:[`To absorb most nutrients from food`,`To absorb water and form/store solid waste`,`To produce insulin`,`To begin protein digestion`], ans:1, exp:`After most nutrients have already been absorbed in the small intestine, the large intestine absorbs remaining water and compacts the leftover material into solid waste for elimination.` },
      { q:`Which organ produces bile, a substance that helps digest fats?`, ch:[`Pancreas`,`Liver`,`Stomach`,`Large intestine`], ans:1, exp:`The liver produces bile, which is stored in the gallbladder and released into the small intestine to help break down (emulsify) fats for digestion.` },
      { q:`Which organ produces digestive enzymes released into the small intestine to help break down carbohydrates, proteins, and fats?`, ch:[`Pancreas`,`Gallbladder`,`Esophagus`,`Large intestine`], ans:0, exp:`The pancreas produces a variety of digestive enzymes, which it releases into the small intestine to help digest carbohydrates, proteins, and fats; it also produces the hormone insulin.` },
      { q:`Vitamins and minerals are best described as nutrients that:`, ch:[`Provide most of the body's calories`,`Are needed in small amounts to support body processes, but are not a major energy source themselves`,`Are only found in meat`,`Have no role in the human body`], ans:1, exp:`Vitamins and minerals are micronutrients needed in relatively small amounts to support processes like bone growth and immune function, but unlike carbohydrates, proteins, and fats, they do not provide significant calories themselves.` },
      { q:`Which macronutrient is generally considered the body's preferred, primary source of quick energy?`, ch:[`Carbohydrates`,`Vitamins`,`Water`,`Fiber`], ans:0, exp:`Carbohydrates are broken down into glucose relatively quickly and are generally the body's preferred and most readily available source of energy.` },
      { q:`What role does dietary fiber play, even though it is not digested by the body?`, ch:[`It provides the most calories of any nutrient`,`It helps move food through the digestive tract and supports digestive health`,`It replaces the need for water`,`It is fully absorbed into the bloodstream`], ans:1, exp:`Fiber is not broken down by human digestive enzymes, but it adds bulk that helps move food through the intestines and supports overall digestive health.` },
      { q:`Why is water important for digestion and overall body function?`, ch:[`It has no real role in digestion`,`It helps break down food, transport nutrients, and prevent dehydration`,`It only matters for the respiratory system`,`It is classified as a macronutrient that provides calories`], ans:1, exp:`Water helps dissolve and transport nutrients, supports chemical digestion reactions, and keeps the digestive system functioning properly, all while preventing dehydration.` },
    ]
  },
];
